namespace Stackshot
{
    public static partial class I18n
    {
        static void RegisterKoreanHome(Dictionary<string, string> map)
        {
            RegisterKoreanHomeSettings(map);
            RegisterKoreanHomeMascot(map);
            RegisterKoreanHomeDialogue(map);
        }

        static void RegisterKoreanHomeSettings(Dictionary<string, string> map)
        {
            map["{0} setting matches {1}."] = "{1}\uC5D0 \uC77C\uCE58\uD558\uB294 \uC124\uC815 {0}\uAC1C";
            map["Lv. {0}"] = "\uB808\uBCA8 {0}";
            map["Only counts active time at the PC: if you step away for 5 minutes, your eyes and body have rested and timer resets. Never interrupts during calls, presentations, recordings, full screen, or Windows Focus Assist: waits until you finish. Take a break anytime from the desktop mascot menu (\u201CTake a break with me\u201D)."] = "PC\uB97C \uC2E4\uC81C\uB85C \uC0AC\uC6A9\uD558\uB294 \uC2DC\uAC04\uB9CC \uC149\uB2C8\uB2E4. \uC790\uB9AC\uB97C 5\uBD84 \uBE44\uC6B0\uBA74 \uD734\uC2DD\uC73C\uB85C \uBCF4\uACE0 \uD0C0\uC774\uBA38\uB97C \uCD08\uAE30\uD654\uD569\uB2C8\uB2E4. \uD1B5\uD654, \uBC1C\uD45C, \uB179\uD654, \uC804\uCCB4 \uD654\uBA74 \uB610\uB294 Windows \uC9D1\uC911 \uC9C0\uC6D0 \uC0AC\uC6A9 \uC911\uC5D0\uB294 \uB05D\uB0A0 \uB54C\uAE4C\uC9C0 \uAE30\uB2E4\uB9BD\uB2C8\uB2E4. \uBC14\uD0D5 \uD654\uBA74 \uB9C8\uC2A4\uCF54\uD2B8 \uBA54\uB274\uC758 \u2018\uD568\uAED8 \uC26C\uAE30\u2019\uB85C \uC5B8\uC81C\uB4E0\uC9C0 \uC274 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
            map["Start from here or from the mascot desktop menu (\u201CFocus\u201D). During focus, mascot quietly reads by your side without speaking, wearing a timer on its head. Healthy breaks wait until rest periods. If you step away for 5+ minutes, timer pauses. Without the mascot on desktop, runs quietly and notifies via system toasts."] = "\uC5EC\uAE30 \uB610\uB294 \uBC14\uD0D5 \uD654\uBA74 \uB9C8\uC2A4\uCF54\uD2B8\uC758 \u2018\uC9D1\uC911\u2019 \uBA54\uB274\uC5D0\uC11C \uC2DC\uC791\uD558\uC138\uC694. \uC9D1\uC911\uD558\uB294 \uB3D9\uC548 \uB9C8\uC2A4\uCF54\uD2B8\uB294 \uBA38\uB9AC\uC5D0 \uD0C0\uC774\uBA38\uB97C \uC5B9\uACE0 \uC870\uC6A9\uD788 \uCC45\uC744 \uC77D\uC2B5\uB2C8\uB2E4. \uAC74\uAC15 \uC54C\uB9BC\uC740 \uD734\uC2DD \uC2DC\uAC04\uAE4C\uC9C0 \uAE30\uB2E4\uB9AC\uACE0, \uC790\uB9AC\uB97C 5\uBD84 \uC774\uC0C1 \uBE44\uC6B0\uBA74 \uD0C0\uC774\uBA38\uAC00 \uBA48\uCDA5\uB2C8\uB2E4. \uBC14\uD0D5 \uD654\uBA74 \uB9C8\uC2A4\uCF54\uD2B8\uAC00 \uAEBC\uC838 \uC788\uC73C\uBA74 \uC2DC\uC2A4\uD15C \uC54C\uB9BC\uC73C\uB85C \uC54C\uB824 \uC90D\uB2C8\uB2E4.";
            map["Everything stays local. With smartwatch connected, data travels directly between Google and your PC; credentials are encrypted with Windows DPAPI and you can disconnect anytime. Mascot offers encouragement, not medical advice. If you sleep under 6 hours, break intervals adapt slightly earlier; if you recently walked, movement pauses wait; once daily water goal is reached, reminders stop."] = "\uB370\uC774\uD130\uB294 \uC774 \uAE30\uAE30\uC5D0 \uC800\uC7A5\uD569\uB2C8\uB2E4. \uC6CC\uCE58\uB97C \uC5F0\uACB0\uD558\uBA74 PC\uC640 Google\uC774 \uC9C1\uC811 \uD1B5\uC2E0\uD569\uB2C8\uB2E4. \uC778\uC99D \uC815\uBCF4\uB294 Windows DPAPI\uB85C \uC554\uD638\uD654\uD558\uBA70 \uC5B8\uC81C\uB4E0\uC9C0 \uC5F0\uACB0\uC744 \uB04A\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB9C8\uC2A4\uCF54\uD2B8\uB294 \uC77C\uC0C1\uC758 \uAC74\uAC15 \uC2B5\uAD00\uC744 \uC751\uC6D0\uD558\uBA70 \uC758\uB8CC \uC870\uC5B8\uC744 \uC81C\uACF5\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC218\uBA74\uC774 6\uC2DC\uAC04 \uBBF8\uB9CC\uC774\uBA74 \uC870\uAE08 \uC77C\uCC0D \uD734\uC2DD\uC744 \uAD8C\uD558\uACE0, \uCD5C\uADFC\uC5D0 \uAC78\uC5C8\uB2E4\uBA74 \uC6C0\uC9C1\uC774\uAE30 \uC54C\uB9BC\uC744 \uBBF8\uB8F9\uB2C8\uB2E4. \uBB3C \uC12D\uCDE8 \uBAA9\uD45C\uB97C \uB2EC\uC131\uD558\uBA74 \uD574\uB2F9 \uC54C\uB9BC\uC744 \uBA48\uCDA5\uB2C8\uB2E4.";
            map["You can also drag & drop files onto the mascot: images go to editor, videos to player, XML/Markdown to viewer, text to notes, folders to quick links. Reminders wait until you are active, and overdue reminders alert upon wake."] = "\uD30C\uC77C\uC744 \uB9C8\uC2A4\uCF54\uD2B8\uC5D0 \uB04C\uC5B4\uB2E4 \uB193\uC73C\uBA74 \uC774\uBBF8\uC9C0\uB294 \uD3B8\uC9D1\uAE30, \uB3D9\uC601\uC0C1\uC740 \uD50C\uB808\uC774\uC5B4, XML\uACFC Markdown\uC740 \uBDF0\uC5B4\uB85C \uC5FD\uB2C8\uB2E4. \uD14D\uC2A4\uD2B8\uB294 \uBA54\uBAA8\uC5D0, \uD3F4\uB354\uB294 \uBC14\uB85C\uAC00\uAE30\uC5D0 \uCD94\uAC00\uD569\uB2C8\uB2E4. \uC54C\uB9BC\uC740 PC\uB97C \uB2E4\uC2DC \uC0AC\uC6A9\uD560 \uB54C \uD45C\uC2DC\uD558\uBA70, \uC808\uC804 \uC911\uC5D0 \uC9C0\uB09C \uC54C\uB9BC\uC740 \uC808\uC804 \uD574\uC81C \uD6C4 \uC54C\uB824 \uC90D\uB2C8\uB2E4.";
            map["On the desktop it consumes slightly more: ~10 MB RAM and ~1% CPU while moving (almost none while sleeping). Automatically hides during full-screen games or presentations, and never appears in screenshots or screen shares. Click to open menu, rapid clicks to tickle; drag anywhere you like."] = "\uBC14\uD0D5 \uD654\uBA74\uC5D0\uC11C\uB294 \uBA54\uBAA8\uB9AC\uB97C \uC57D 10MB, \uC6C0\uC9C1\uC77C \uB54C CPU\uB97C \uC57D 1% \uC0AC\uC6A9\uD569\uB2C8\uB2E4. \uC7A0\uB4E4\uBA74 CPU\uB97C \uAC70\uC758 \uC0AC\uC6A9\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC804\uCCB4 \uD654\uBA74 \uAC8C\uC784\uC774\uB098 \uBC1C\uD45C \uC911\uC5D0\uB294 \uC790\uB3D9\uC73C\uB85C \uC228\uACE0 \uCEA1\uCC98\uC640 \uD654\uBA74 \uACF5\uC720\uC5D0\uB3C4 \uB098\uD0C0\uB098\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uD074\uB9AD\uD558\uBA74 \uBA54\uB274\uAC00 \uC5F4\uB9AC\uACE0 \uC5F0\uB2EC\uC544 \uD074\uB9AD\uD558\uBA74 \uAC04\uC9C0\uB7FC\uC744 \uD0D1\uB2C8\uB2E4. \uC6D0\uD558\uB294 \uACF3\uC73C\uB85C \uB04C\uC5B4 \uC62E\uAE30\uC138\uC694.";
            map["The mascot uses your activity data to care for you: alerts after an hour of inactivity, encourages movement in morning/afternoon, celebrates walks, active minutes and step goals, adapts breaks if you had poor sleep, and includes steps in daily summary."] = "\uB9C8\uC2A4\uCF54\uD2B8\uB294 \uD65C\uB3D9 \uAE30\uB85D\uC744 \uBCF4\uACE0 \uD55C \uC2DC\uAC04 \uB3D9\uC548 \uC6C0\uC9C1\uC774\uC9C0 \uC54A\uC73C\uBA74 \uC54C\uB824 \uC90D\uB2C8\uB2E4. \uC544\uCE68\uACFC \uC624\uD6C4\uC5D0 \uC6C0\uC9C1\uC784\uC744 \uAD8C\uD558\uACE0 \uC0B0\uCC45, \uD65C\uB3D9 \uC2DC\uAC04, \uAC78\uC74C \uBAA9\uD45C \uB2EC\uC131\uC744 \uCD95\uD558\uD569\uB2C8\uB2E4. \uC7A0\uC744 \uC124\uCCE4\uB2E4\uBA74 \uD734\uC2DD \uAC04\uACA9\uC744 \uC870\uC815\uD558\uACE0 \uD558\uB8E8 \uC694\uC57D\uC5D0 \uAC78\uC74C \uC218\uB3C4 \uD45C\uC2DC\uD569\uB2C8\uB2E4.";
            map["You cancelled the connection."] = "\uC5F0\uACB0\uC744 \uCDE8\uC18C\uD588\uC2B5\uB2C8\uB2E4.";
            map["The Google Health connection is not set up."] = "Google Health \uC5F0\uACB0\uC774 \uC124\uC815\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.";
            map["Port {0} is busy: close whatever uses it and try again."] = "{0}\uBC88 \uD3EC\uD2B8\uB97C \uC0AC\uC6A9 \uC911\uC778 \uD504\uB85C\uADF8\uB7A8\uC744 \uB2EB\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.";
            map["Could not open login: "] = "\uB85C\uADF8\uC778 \uCC3D\uC744 \uC5F4 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. ";
            map["Could not connect: "] = "\uC5F0\uACB0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. ";
            map["Page not found"] = "\uD398\uC774\uC9C0\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4";
            map["This address does not belong to Stackshot."] = "Stackshot\uC5D0\uC11C \uC0AC\uC6A9\uD558\uB294 \uC8FC\uC18C\uAC00 \uC544\uB2D9\uB2C8\uB2E4.";
            map["Connection cancelled"] = "\uC5F0\uACB0 \uCDE8\uC18C\uB428";
            map["Nothing was connected. You can close this tab and try again whenever you like from Stackshot."] = "\uC5F0\uACB0\uB41C \uAE30\uAE30\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uC774 \uD0ED\uC744 \uB2EB\uACE0 \uC5B8\uC81C\uB4E0\uC9C0 Stackshot\uC5D0\uC11C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.";
            map["Could not connect"] = "\uC5F0\uACB0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4";
            map["Google returned \u201C{0}\u201D. Close this tab and try again from Stackshot."] = "Google\uC5D0\uC11C \u201C{0}\u201D\uC744 \uBC18\uD658\uD588\uC2B5\uB2C8\uB2E4. \uD0ED\uC744 \uB2EB\uACE0 Stackshot\uC5D0\uC11C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.";
            map["Google said: {0}"] = "Google \uC751\uB2F5: {0}";
            map["Invalid response"] = "\uC798\uBABB\uB41C \uC751\uB2F5";
            map["This response is not from the login opened by Stackshot. Try again from the app."] = "Stackshot\uC5D0\uC11C \uC2DC\uC791\uD55C \uB85C\uADF8\uC778\uC5D0 \uB300\uD55C \uC751\uB2F5\uC774 \uC544\uB2D9\uB2C8\uB2E4. \uC571\uC5D0\uC11C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.";
            map["Watch "] = "\uC6CC\uCE58 ";
            map["connected"] = "\uC5F0\uACB0\uB428";
            map["Stackshot can now see your steps, activity and sleep. You can close this tab and return to the app."] = "\uC774\uC81C Stackshot\uC5D0\uC11C \uAC78\uC74C \uC218, \uD65C\uB3D9, \uC218\uBA74 \uC815\uBCF4\uB97C \uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD0ED\uC744 \uB2EB\uACE0 \uC571\uC73C\uB85C \uB3CC\uC544\uAC00\uC138\uC694.";
            map[" Close this tab and try again from Stackshot."] = " \uC774 \uD0ED\uC744 \uB2EB\uACE0 Stackshot\uC5D0\uC11C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.";
            map["Login timed out. Try again."] = "\uB85C\uADF8\uC778 \uC2DC\uAC04\uC774 \uCD08\uACFC\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.";
            map["Google no longer accepts the connection: connect your watch again."] = "Google \uC5F0\uACB0\uC774 \uB9CC\uB8CC\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC6CC\uCE58\uB97C \uB2E4\uC2DC \uC5F0\uACB0\uD558\uC138\uC694.";
            map["The relay is missing the Google key."] = "\uC911\uACC4 \uC11C\uBC84\uC5D0 Google \uD0A4\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.";
            map["Google is not responding ({0})."] = "Google\uC5D0\uC11C \uC751\uB2F5\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4({0}).";
            map["No connection to Google."] = "Google\uC5D0 \uC5F0\uACB0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.";
            map["Google did not provide the keys."] = "Google\uC5D0\uC11C \uD0A4\uB97C \uC81C\uACF5\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.";
            map["Google did not provide a lasting key: connect again."] = "Google\uC5D0\uC11C \uC7A5\uAE30 \uC778\uC99D \uD0A4\uB97C \uC81C\uACF5\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uC5F0\uACB0\uD558\uC138\uC694.";
            map["Not connected."] = "\uC5F0\uACB0\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.";
            map["Google won't let Stackshot read the data: check that the watch is linked in the Google Health app."] = "Google\uC5D0\uC11C \uB370\uC774\uD130 \uC77D\uAE30\uB97C \uD5C8\uC6A9\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. Google Health \uC571\uC5D0\uC11C \uC6CC\uCE58 \uC5F0\uACB0\uC744 \uD655\uC778\uD558\uC138\uC694.";
            map["Google asks to wait a moment."] = "\uC7A0\uC2DC \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD574 \uB2EC\uB77C\uB294 Google \uC751\uB2F5\uC744 \uBC1B\uC558\uC2B5\uB2C8\uB2E4.";
            map["Today"] = "\uC624\uB298";
            map["Yesterday"] = "\uC5B4\uC81C";
            map["This week"] = "\uC774\uBC88 \uC8FC";
            map["This month"] = "\uC774\uBC88 \uB2EC";
            map["Earlier"] = "\uC774\uC804";
            map["Backdrop & editor"] = "\uBC30\uACBD \uBC0F \uD3B8\uC9D1\uAE30";
            map["Like CleanShot X: your captures ready to present with a beautiful backdrop, padding, and shadow. In the editor, use the Backdrop button (or key B); also for videos and GIFs with \u201CPresent\u201D."] = "CleanShot X\uCC98\uB7FC \uCEA1\uCC98\uC5D0 \uBC30\uACBD, \uC5EC\uBC31, \uADF8\uB9BC\uC790\uB97C \uB354\uD574 \uBC1C\uD45C\uC6A9 \uC774\uBBF8\uC9C0\uB97C \uB9CC\uB4DC\uC138\uC694. \uD3B8\uC9D1\uAE30\uC758 \uBC30\uACBD \uBC84\uD2BC\uC774\uB098 B \uD0A4\uB97C \uC0AC\uC6A9\uD558\uC138\uC694. \uB3D9\uC601\uC0C1\uACFC GIF\uC5D0\uB294 \u2018\uBC1C\uD45C\uC6A9\u2019 \uC635\uC158\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
            map["Backdrop preview"] = "\uBC30\uACBD \uBBF8\uB9AC \uBCF4\uAE30";
            map["Custom backdrops"] = "\uC0AC\uC6A9\uC790 \uBC30\uACBD";
            map["You are using your own image. You can add more or remove this one."] = "\uB0B4 \uC774\uBBF8\uC9C0\uB97C \uC0AC\uC6A9 \uC911\uC785\uB2C8\uB2E4. \uC774\uBBF8\uC9C0\uB97C \uB354 \uCD94\uAC00\uD558\uAC70\uB098 \uC774 \uBC30\uACBD\uC744 \uC0AD\uC81C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
            map["Add a photo or image and use it as backdrop for your captures."] = "\uC0AC\uC9C4\uC774\uB098 \uC774\uBBF8\uC9C0\uB97C \uCD94\uAC00\uD574 \uCEA1\uCC98 \uBC30\uACBD\uC73C\uB85C \uC0AC\uC6A9\uD558\uC138\uC694.";
            map["Add image\u2026"] = "\uC774\uBBF8\uC9C0 \uCD94\uAC00\u2026";
            map["Remove this backdrop"] = "\uC774 \uBC30\uACBD \uC0AD\uC81C";
            map["Deletes the copy saved in Stackshot; your original image is untouched."] = "Stackshot\uC5D0 \uC800\uC7A5\uB41C \uC0AC\uBCF8\uB9CC \uC0AD\uC81C\uD558\uBA70 \uC6D0\uBCF8 \uC774\uBBF8\uC9C0\uB294 \uC720\uC9C0\uB429\uB2C8\uB2E4.";
            map["Open editor with backdrop enabled"] = "\uBC30\uACBD\uC744 \uCF20 \uC0C1\uD0DC\uB85C \uD3B8\uC9D1\uAE30 \uC5F4\uAE30";
            map["Otherwise, enable it with the Backdrop button anytime."] = "\uD3B8\uC9D1\uAE30\uC758 \uBC30\uACBD \uBC84\uD2BC\uC73C\uB85C \uC5B8\uC81C\uB4E0\uC9C0 \uCF24 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
            map["Style"] = "\uC2A4\uD0C0\uC77C";
            map["Custom, from editor"] = "\uD3B8\uC9D1\uAE30\uC5D0\uC11C \uC9C1\uC811 \uC124\uC815";
            map["In the editor you have more: plain colors, blurred capture, inset, alignment, and sliders for padding, shadow, and corners; what you last used is saved here."] = "\uD3B8\uC9D1\uAE30\uC5D0\uC11C \uB2E8\uC0C9 \uBC30\uACBD, \uCEA1\uCC98 \uD750\uB9BC, \uC548\uCABD \uC5EC\uBC31, \uC815\uB82C\uC744 \uC9C0\uC815\uD558\uACE0 \uC5EC\uBC31\u00B7\uADF8\uB9BC\uC790\u00B7\uBAA8\uC11C\uB9AC\uB97C \uC870\uC808\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB9C8\uC9C0\uB9C9\uC73C\uB85C \uC0AC\uC6A9\uD55C \uAC12\uC774 \uC5EC\uAE30\uC5D0 \uC800\uC7A5\uB429\uB2C8\uB2E4.";
            map["Reset style"] = "\uC2A4\uD0C0\uC77C \uCD08\uAE30\uD654";
