            map["Ready to paste immediately with Ctrl+V; videos and GIFs as files."] = "Ctrl+V\uB85C \uBC14\uB85C \uBD99\uC5EC\uB123\uC2B5\uB2C8\uB2E4. \uB3D9\uC601\uC0C1\uACFC GIF\uB294 \uD30C\uC77C\uB85C \uBCF5\uC0AC\uD569\uB2C8\uB2E4.";
            map["Auto-hide thumbnails"] = "\uC378\uB124\uC77C \uC790\uB3D9 \uC228\uAE40";
            map["When unused, tuck thumbnails into screen edge until hovered."] = "\uC0AC\uC6A9\uD558\uC9C0 \uC54A\uB294 \uC378\uB124\uC77C\uC740 \uD654\uBA74 \uAC00\uC7A5\uC790\uB9AC\uB85C \uC228\uAE30\uACE0 \uB9C8\uC6B0\uC2A4\uB97C \uC62C\uB9AC\uBA74 \uB2E4\uC2DC \uD45C\uC2DC\uD569\uB2C8\uB2E4.";
            map["Never"] = "\uC0AC\uC6A9 \uC548 \uD568";
            map["After 3 s"] = "3\uCD08 \uD6C4";
            map["After 5 s"] = "5\uCD08 \uD6C4";
            map["After 10 s"] = "10\uCD08 \uD6C4";
            map["Countdown timer"] = "\uCEA1\uCC98 \uD0C0\uC774\uBA38";
            map["Select area and counts down before capture: gives time to open menus. Esc cancels."] = "\uC601\uC5ED \uC120\uD0DD \uD6C4 \uCE74\uC6B4\uD2B8\uB2E4\uC6B4\uD558\uB294 \uB3D9\uC548 \uBA54\uB274\uB97C \uC5F4 \uC218 \uC788\uC2B5\uB2C8\uB2E4. Esc\uB85C \uCDE8\uC18C\uD569\uB2C8\uB2E4.";
            map["Follow cursor across monitors"] = "\uBAA8\uB2C8\uD130 \uAC04 \uCEE4\uC11C \uB530\uB77C\uAC00\uAE30";
            map["On multi-monitor setups, thumbnails appear on the active screen."] = "\uC5EC\uB7EC \uBAA8\uB2C8\uD130\uB97C \uC0AC\uC6A9\uD560 \uB54C \uD604\uC7AC \uC791\uC5C5 \uC911\uC778 \uD654\uBA74\uC5D0 \uC378\uB124\uC77C\uC744 \uD45C\uC2DC\uD569\uB2C8\uB2E4.";
            map["Include mouse cursor"] = "\uB9C8\uC6B0\uC2A4 \uCEE4\uC11C \uD3EC\uD568";
            map["The mouse cursor is captured where it was when capture started."] = "\uCEA1\uCC98\uB97C \uC2DC\uC791\uD560 \uB54C\uC758 \uB9C8\uC6B0\uC2A4 \uC704\uCE58\uC5D0 \uCEE4\uC11C\uB97C \uD45C\uC2DC\uD569\uB2C8\uB2E4.";
            map["National IDs, Social Security numbers, IBANs, cards, emails and phone numbers are covered automatically in every capture. They are read on your computer; nothing leaves it."] = "\uBAA8\uB4E0 \uCEA1\uCC98\uC5D0\uC11C \uC2E0\uBD84\uC99D \uBC88\uD638, \uC0AC\uD68C\uBCF4\uC7A5\uBC88\uD638, IBAN, \uCE74\uB4DC \uBC88\uD638, \uC774\uBA54\uC77C, \uC804\uD654\uBC88\uD638\uB97C \uC790\uB3D9\uC73C\uB85C \uAC00\uB9BD\uB2C8\uB2E4. \uC774 \uCEF4\uD4E8\uD130\uC5D0\uC11C\uB9CC \uCC98\uB9AC\uD569\uB2C8\uB2E4.";
            map["When off, you decide: in the editor, \u201CSensitive data\u201D covers them with marks you can remove."] = "\uB044\uBA74 \uD3B8\uC9D1\uAE30\uC758 \u2018\uBBFC\uAC10 \uC815\uBCF4\u2019\uC5D0\uC11C \uC9C1\uC811 \uAC00\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAC00\uB9BC \uD45C\uC2DC\uB294 \uB2E4\uC2DC \uC9C0\uC6B8 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
            map["Saved captures"] = "\uC800\uC7A5\uB41C \uCEA1\uCC98";
            map["Automatically save all captures"] = "\uBAA8\uB4E0 \uCEA1\uCC98 \uC790\uB3D9 \uC800\uC7A5";
            map["Every capture and recording is saved to your folder. When off, only those manually kept."] = "\uBAA8\uB4E0 \uCEA1\uCC98\uC640 \uB179\uD654\uB97C \uC9C0\uC815\uD55C \uD3F4\uB354\uC5D0 \uC800\uC7A5\uD569\uB2C8\uB2E4. \uB044\uBA74 \uC9C1\uC811 \uC800\uC7A5\uD55C \uD56D\uBAA9\uB9CC \uB0A8\uC2B5\uB2C8\uB2E4.";
            map["Files not in your save folder are deleted automatically based on Recents retention (never while shown as thumbnail or in editor)."] = "\uC800\uC7A5 \uD3F4\uB354 \uBC16\uC5D0 \uC788\uB294 \uD30C\uC77C\uC740 \uCD5C\uADFC \uD56D\uBAA9 \uBCF4\uAD00 \uAE30\uAC04\uC774 \uC9C0\uB098\uBA74 \uC0AD\uC81C\uD569\uB2C8\uB2E4. \uC378\uB124\uC77C\uC774\uB098 \uD3B8\uC9D1\uAE30\uC5D0 \uC5F4\uB9B0 \uD30C\uC77C\uC740 \uC720\uC9C0\uD569\uB2C8\uB2E4.";
            map["Advanced"] = "\uACE0\uAE09";
            map["Open new XML files from a folder"] = "\uD3F4\uB354\uC5D0 \uCD94\uAC00\uB41C XML \uD30C\uC77C \uC5F4\uAE30";
            map["Designed for programs that save SOAP messages as XML files in a folder. In the viewer, [ and ] navigate between XML files, and \u201CMore options\u201D lists the latest ones that arrived."] = "\uD3F4\uB354\uC5D0 SOAP \uBA54\uC2DC\uC9C0\uB97C XML\uB85C \uC800\uC7A5\uD558\uB294 \uD504\uB85C\uADF8\uB7A8\uC744 \uC704\uD55C \uAE30\uB2A5\uC785\uB2C8\uB2E4. \uBDF0\uC5B4\uC5D0\uC11C [ \uBC0F ] \uD0A4\uB85C XML \uD30C\uC77C\uC744 \uC774\uB3D9\uD558\uACE0 \u2018\uB354 \uB9CE\uC740 \uC635\uC158\u2019\uC5D0\uC11C \uCD5C\uADFC \uD30C\uC77C\uC744 \uBD05\uB2C8\uB2E4.";
            map["Every XML file appearing in that folder opens automatically in the Stackshot viewer."] = "\uC120\uD0DD\uD55C \uD3F4\uB354\uC5D0 \uC0C8 XML \uD30C\uC77C\uC774 \uC0DD\uAE30\uBA74 Stackshot \uBDF0\uC5B4\uB85C \uC790\uB3D9\uC73C\uB85C \uC5FD\uB2C8\uB2E4.";
            map["Choose the folder to monitor below."] = "\uC544\uB798\uC5D0\uC11C \uAC10\uC2DC\uD560 \uD3F4\uB354\uB97C \uC120\uD0DD\uD558\uC138\uC694.";
            map["Folder does not exist yet; Stackshot checks again every minute."] = "\uD3F4\uB354\uAC00 \uC544\uC9C1 \uC5C6\uC2B5\uB2C8\uB2E4. 1\uBD84\uB9C8\uB2E4 \uB2E4\uC2DC \uD655\uC778\uD569\uB2C8\uB2E4.";
            map["Active: new XML files open automatically in the viewer."] = "\uD65C\uC131: \uC0C8 XML \uD30C\uC77C\uC744 \uBDF0\uC5B4\uC5D0\uC11C \uC790\uB3D9\uC73C\uB85C \uC5FD\uB2C8\uB2E4.";
            map["No folder"] = "\uD3F4\uB354 \uC5C6\uC74C";
            map["Folder chosen by you."] = "\uC9C1\uC811 \uC120\uD0DD\uD55C \uD3F4\uB354\uC785\uB2C8\uB2E4.";
            map["Choose the folder where XML files appear."] = "XML \uD30C\uC77C\uC774 \uC0DD\uC131\uB418\uB294 \uD3F4\uB354\uB97C \uC120\uD0DD\uD558\uC138\uC694.";
            map["Choose\u2026"] = "\uC120\uD0DD\u2026";
            map["Which folder to monitor? Every new XML appearing in it opens in viewer."] = "\uAC10\uC2DC\uD560 \uD3F4\uB354\uB97C \uC120\uD0DD\uD558\uC138\uC694. \uC0C8 XML \uD30C\uC77C\uC740 \uBDF0\uC5B4\uC5D0\uC11C \uC790\uB3D9\uC73C\uB85C \uC5F4\uB9BD\uB2C8\uB2E4.";
            map["Stackshot now appears among the apps that can open {0}."] = "\uC774\uC81C {0} \uD30C\uC77C\uC744 \uC5F4 \uC218 \uC788\uB294 \uC571 \uBAA9\uB85D\uC5D0 Stackshot\uC774 \uD45C\uC2DC\uB429\uB2C8\uB2E4.";
            map["Choose Stackshot for {0} in the Windows window that opens now: Windows asks you to make that choice yourself."] = "\uACE7 \uC5F4\uB9AC\uB294 Windows \uCC3D\uC5D0\uC11C {0}\uC758 \uAE30\uBCF8 \uC571\uC73C\uB85C Stackshot\uC744 \uC120\uD0DD\uD558\uC138\uC694. Windows\uC5D0\uC11C \uC0AC\uC6A9\uC790\uAC00 \uC9C1\uC811 \uC9C0\uC815\uD574\uC57C \uD569\uB2C8\uB2E4.";
            map["Open that window"] = "\uC124\uC815 \uCC3D \uC5F4\uAE30";
            map["Double-click a {0} (Cinema masters that Windows Media Player won't open) to view in Stackshot player at actual size."] = "{0} \uD30C\uC77C\uC744 \uB450 \uBC88 \uD074\uB9AD\uD558\uBA74 Stackshot\uC5D0\uC11C \uC6D0\uB798 \uD06C\uAE30\uB85C \uC7AC\uC0DD\uD569\uB2C8\uB2E4. Windows \uBBF8\uB514\uC5B4 \uD50C\uB808\uC774\uC5B4\uC5D0\uC11C \uC5F4 \uC218 \uC5C6\uB294 \uC2DC\uB124\uB9C8 \uC6D0\uBCF8\uB3C4 \uC9C0\uC6D0\uD569\uB2C8\uB2E4.";
            map["Double-click a {0} to open it in the Stackshot viewer."] = "{0} \uD30C\uC77C\uC744 \uB450 \uBC88 \uD074\uB9AD\uD558\uBA74 Stackshot \uBDF0\uC5B4\uB85C \uC5FD\uB2C8\uB2E4.";
            map["Stackshot is the default app for {0}."] = "Stackshot\uC774 {0}\uC758 \uAE30\uBCF8 \uC571\uC785\uB2C8\uB2E4.";
            map["Registered, but Windows opens {0} with another app. Choose Stackshot in Default Apps."] = "Stackshot\uC740 \uB4F1\uB85D\uB418\uC5B4 \uC788\uC9C0\uB9CC {0} \uD30C\uC77C\uC744 \uB2E4\uB978 \uC571\uC73C\uB85C \uC5F4\uACE0 \uC788\uC2B5\uB2C8\uB2E4. \uAE30\uBCF8 \uC571\uC5D0\uC11C Stackshot\uC744 \uC120\uD0DD\uD558\uC138\uC694.";
            map["Delete temporary captures?"] = "\uC784\uC2DC \uCEA1\uCC98\uB97C \uC0AD\uC81C\uD560\uAE4C\uC694?";
            map["Saved captures in your folder will not be touched."] = "\uC9C0\uC815\uD55C \uD3F4\uB354\uC5D0 \uC800\uC7A5\uD55C \uCEA1\uCC98\uB294 \uC720\uC9C0\uD569\uB2C8\uB2E4.";
            map["Recent captures cleared"] = "\uCD5C\uADFC \uCEA1\uCC98\uB97C \uBE44\uC6E0\uC2B5\uB2C8\uB2E4";
            map["Temporary captures have been deleted. Those in your folder remain."] = "\uC784\uC2DC \uCEA1\uCC98\uB97C \uC0AD\uC81C\uD588\uC2B5\uB2C8\uB2E4. \uC800\uC7A5 \uD3F4\uB354\uC758 \uCEA1\uCC98\uB294 \uC720\uC9C0\uD569\uB2C8\uB2E4.";
            map["Downloaded, signature verified and installed automatically when your PC is idle."] = "\uCEF4\uD4E8\uD130\uB97C \uC0AC\uC6A9\uD558\uC9C0 \uC54A\uC744 \uB54C \uB2E4\uC6B4\uB85C\uB4DC\uD558\uACE0 \uC11C\uBA85\uC744 \uAC80\uC99D\uD55C \uB4A4 \uC790\uB3D9 \uC124\uCE58\uD569\uB2C8\uB2E4.";
            map["Managed by IT on this PC: Stackshot will only notify you of new versions."] = "\uC774 PC\uB294 IT \uBD80\uC11C\uAC00 \uAD00\uB9AC\uD569\uB2C8\uB2E4. Stackshot\uC740 \uC0C8 \uBC84\uC804\uC774 \uC788\uC73C\uBA74 \uC54C\uB9BC\uB9CC \uD45C\uC2DC\uD569\uB2C8\uB2E4.";
            map["Only with Stackshot installed; portable copy cannot self-install."] = "\uC124\uCE58\uB41C Stackshot\uC5D0\uC11C\uB9CC \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD3EC\uD130\uBE14 \uBC84\uC804\uC740 \uC9C1\uC811 \uC124\uCE58\uD574\uC57C \uD569\uB2C8\uB2E4.";
            map["Requires \u201CCheck for updates\u201D: cannot install without checking."] = "\u2018\uC5C5\uB370\uC774\uD2B8 \uD655\uC778\u2019\uC744 \uBA3C\uC800 \uCF1C\uC57C \uC124\uCE58\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
            map["Checks GitHub for new versions on launch and every 3 hours. Does not send any personal data."] = "\uC571\uC744 \uC2DC\uC791\uD560 \uB54C\uC640 \uC774\uD6C4 3\uC2DC\uAC04\uB9C8\uB2E4 GitHub\uC5D0\uC11C \uC0C8 \uBC84\uC804\uC744 \uD655\uC778\uD569\uB2C8\uB2E4. \uAC1C\uC778 \uB370\uC774\uD130\uB294 \uBCF4\uB0B4\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.";
            map["Mascot settings"] = "\uB9C8\uC2A4\uCF54\uD2B8 \uC124\uC815";
            map["Personality, dialogue, and roaming the desktop."] = "\uC131\uACA9, \uB300\uD654, \uBC14\uD0D5 \uD654\uBA74\uC5D0\uC11C\uC758 \uD589\uB3D9\uC744 \uC124\uC815\uD569\uB2C8\uB2E4.";
            map["On Home and at the bottom of the sidebar."] = "\uD648 \uBC0F \uC0AC\uC774\uB4DC\uBC14 \uD558\uB2E8\uC5D0 \uD45C\uC2DC\uD569\uB2C8\uB2E4.";
            map["Personality"] = "\uC131\uACA9";
            map["What it says and how it moves."] = "\uB9D0\uD22C\uC640 \uC6C0\uC9C1\uC784\uC744 \uACB0\uC815\uD569\uB2C8\uB2E4.";
            map["Occasionally shares tips and tricks about Stackshot."] = "\uAC00\uB054 Stackshot\uC744 \uC0AC\uC6A9\uD558\uB294 \uD301\uC744 \uC54C\uB824 \uC90D\uB2C8\uB2E4.";
            map["Seasonal costume"] = "\uACC4\uC808 \uC758\uC0C1";
            map["Without a hat, wears a pumpkin on Halloween and Santa hat at Christmas."] = "\uBAA8\uC790\uB97C \uC4F0\uC9C0 \uC54A\uC558\uC744 \uB54C \uD57C\uB7EC\uC708\uC5D0\uB294 \uD638\uBC15, \uD06C\uB9AC\uC2A4\uB9C8\uC2A4\uC5D0\uB294 \uC0B0\uD0C0 \uBAA8\uC790\uB97C \uC501\uB2C8\uB2E4.";
            map["Walks along taskbar, looks around, plays and naps."] = "\uC791\uC5C5 \uD45C\uC2DC\uC904\uC744 \uB530\uB77C \uAC77\uACE0 \uC8FC\uBCC0\uC744 \uC0B4\uD53C\uAC70\uB098 \uB180\uACE0 \uB0AE\uC7A0\uC744 \uC7A1\uB2C8\uB2E4.";
            map["Only with Full profile (in General \u203A Profile)."] = "\uC804\uCCB4 \uD504\uB85C\uD544\uC5D0\uC11C\uB9CC \uC0AC\uC6A9 \uAC00\uB2A5\uD569\uB2C8\uB2E4(\uC77C\uBC18 \u203A \uD504\uB85C\uD544).";
            map["Enable \u201CShow mascot\u201D first."] = "\uBA3C\uC800 \u2018\uB9C8\uC2A4\uCF54\uD2B8 \uD45C\uC2DC\u2019\uB97C \uCF1C\uC138\uC694.";
            map["Climb on windows"] = "\uCC3D \uC704\uC5D0 \uC62C\uB77C\uAC00\uAE30";
            map["Occasionally jumps onto active window and walks on top. Moves along with it."] = "\uAC00\uB054 \uD65C\uC131 \uCC3D \uC704\uB85C \uB6F0\uC5B4\uC62C\uB77C \uAC77\uC2B5\uB2C8\uB2E4. \uCC3D\uC744 \uC6C0\uC9C1\uC774\uBA74 \uD568\uAED8 \uC774\uB3D9\uD569\uB2C8\uB2E4.";
            map["Capture an area"] = "\uC601\uC5ED \uCEA1\uCC98";
            map["Repeat last area"] = "\uB9C8\uC9C0\uB9C9 \uC601\uC5ED \uB2E4\uC2DC \uCEA1\uCC98";
            map["Capture full screen"] = "\uC804\uCCB4 \uD654\uBA74 \uCEA1\uCC98";
            map["Capture active window"] = "\uD65C\uC131 \uCC3D \uCEA1\uCC98";
            map["Copy screen text"] = "\uD654\uBA74 \uD14D\uC2A4\uD2B8 \uBCF5\uC0AC";
            map["View and sort Markdown"] = "Markdown \uBCF4\uAE30 \uBC0F \uC815\uB82C";
            map["Timed capture"] = "\uD0C0\uC774\uBA38 \uCEA1\uCC98";
            map["An area"] = "\uC601\uC5ED";
            map["Last area"] = "\uB9C8\uC9C0\uB9C9 \uC601\uC5ED";
            map["Full screen"] = "\uC804\uCCB4 \uD654\uBA74";
            map["A window"] = "\uCC3D";
            map["Animated GIF"] = "\uC6C0\uC9C1\uC774\uB294 GIF";
            map["With timer"] = "\uD0C0\uC774\uBA38 \uC0AC\uC6A9";
            map["Performance"] = "\uC131\uB2A5";
            map["Balanced"] = "\uADE0\uD615";
            map["Full"] = "\uC804\uCCB4 \uAE30\uB2A5";
            map["Subfolders"] = "\uD558\uC704 \uD3F4\uB354";
            map["Saved captures go to a monthly folder, like {0}-{1}."] = "{0}-{1}\uCC98\uB7FC \uC6D4\uBCC4 \uD3F4\uB354\uC5D0 \uCEA1\uCC98\uB97C \uC800\uC7A5\uD569\uB2C8\uB2E4.";
            map["A folder per year and monthly subfolder inside, like {0}\\{1}."] = "{0}\\{1}\uCC98\uB7FC \uC5F0\uB3C4\uBCC4 \uD3F4\uB354 \uC548\uC5D0 \uC6D4\uBCC4 \uD3F4\uB354\uB97C \uB9CC\uB4ED\uB2C8\uB2E4.";
            map["All files go directly into the chosen folder."] = "\uBAA8\uB4E0 \uD30C\uC77C\uC744 \uC120\uD0DD\uD55C \uD3F4\uB354 \uBC14\uB85C \uC544\uB798\uC5D0 \uC800\uC7A5\uD569\uB2C8\uB2E4.";
            map["\\ / : * ? \" < > | are invalid in file names: replaced with _."] = "\uD30C\uC77C \uC774\uB984\uC5D0 \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uB294 \\ / : * ? \" < > | \uBB38\uC790\uB294 _\uB85C \uBC14\uAFC9\uB2C8\uB2E4.";
            map["If left empty, default file name is used."] = "\uBE44\uC6CC \uB450\uBA74 \uAE30\uBCF8 \uD30C\uC77C \uC774\uB984\uC744 \uC0AC\uC6A9\uD569\uB2C8\uB2E4.";
            map["Without {time} or {n}, duplicate names will append (2), (3)\u2026 at the end."] = "{time}\uC774\uB098 {n}\uC774 \uC5C6\uC73C\uBA74 \uAC19\uC740 \uC774\uB984 \uB4A4\uC5D0 (2), (3)\u2026\uC744 \uBD99\uC785\uB2C8\uB2E4.";
            map["For images; videos and GIFs retain their own names."] = "\uC774\uBBF8\uC9C0\uC5D0 \uC801\uC6A9\uD569\uB2C8\uB2E4. \uB3D9\uC601\uC0C1\uACFC GIF\uB294 \uC790\uCCB4 \uC774\uB984\uC744 \uC720\uC9C0\uD569\uB2C8\uB2E4.";
            map["File names"] = "\uD30C\uC77C \uC774\uB984";
            map["Reset"] = "\uCD08\uAE30\uD654";
            map["Reset to {0}"] = "{0}(\uC73C)\uB85C \uCD08\uAE30\uD654";
            map["No"] = "\uC544\uB2C8\uC694";
            map["By month"] = "\uC6D4\uBCC4";
            map["By year and month"] = "\uC5F0\uB3C4 \uBC0F \uC6D4\uBCC4";
            map["Clicks & keys"] = "\uD074\uB9AD \uBC0F \uD0A4 \uC785\uB825";
            map["Drawn onto the video while recording so viewers can follow your actions. Not shown during pauses."] = "\uC2DC\uCCAD\uC790\uAC00 \uB3D9\uC791\uC744 \uB530\uB77C\uAC08 \uC218 \uC788\uB3C4\uB85D \uB179\uD654 \uC601\uC0C1\uC5D0 \uD45C\uC2DC\uD569\uB2C8\uB2E4. \uC77C\uC2DC \uC815\uC9C0 \uC911\uC5D0\uB294 \uD45C\uC2DC\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.";
            map["Show clicks"] = "\uD074\uB9AD \uD45C\uC2DC";
            map["A circle where you click: blue for left click and orange for right click."] = "\uC67C\uCABD \uD074\uB9AD\uC740 \uD30C\uB780 \uC6D0, \uC624\uB978\uCABD \uD074\uB9AD\uC740 \uC8FC\uD669\uC0C9 \uC6D0\uC73C\uB85C \uD45C\uC2DC\uD569\uB2C8\uB2E4.";
            map["Show keystrokes pressed"] = "\uB204\uB978 \uD0A4 \uD45C\uC2DC";
            map["Shortcuts (Ctrl+C, Alt+Tab, Win+Shift+S\u2026) appear bottom-center. Typed text never appears, keeping your passwords safe."] = "Ctrl+C, Alt+Tab, Win+Shift+S \uAC19\uC740 \uB2E8\uCD95\uD0A4\uB97C \uD654\uBA74 \uC544\uB798 \uAC00\uC6B4\uB370 \uD45C\uC2DC\uD569\uB2C8\uB2E4. \uC785\uB825\uD55C \uD14D\uC2A4\uD2B8\uC640 \uC554\uD638\uB294 \uD45C\uC2DC\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.";
            map["Video with sound (MP4, or lossless MKV in Cinema) and animated GIF. To stop, press the hotkey again or Stop in the recording bar."] = "\uC18C\uB9AC\uB97C \uD3EC\uD568\uD55C \uB3D9\uC601\uC0C1(MP4 \uB610\uB294 \uC2DC\uB124\uB9C8 \uBAA8\uB4DC\uC758 \uBB34\uC190\uC2E4 MKV)\uACFC GIF\uB97C \uB179\uD654\uD569\uB2C8\uB2E4. \uB2E8\uCD95\uD0A4\uB97C \uB2E4\uC2DC \uB204\uB974\uAC70\uB098 \uB179\uD654 \uD45C\uC2DC\uC904\uC758 \uC911\uC9C0\uB97C \uB20C\uB7EC \uB9C8\uCE69\uB2C8\uB2E4.";
            map["How much detail and smoothness each video saves, and file size."] = "\uB179\uD654\uC758 \uC120\uBA85\uB3C4, \uBD80\uB4DC\uB7EC\uC6C0, \uD30C\uC77C \uD06C\uAE30\uB97C \uACB0\uC815\uD569\uB2C8\uB2E4.";
            map["More frames, smoother (and larger file)."] = "\uD504\uB808\uC784 \uC218\uAC00 \uB9CE\uC744\uC218\uB85D \uBD80\uB4DC\uB7FD\uC9C0\uB9CC \uD30C\uC77C\uC774 \uCEE4\uC9D1\uB2C8\uB2E4.";
            map["Memory for motion peaks"] = "\uBE60\uB978 \uC6C0\uC9C1\uC784\uC5D0 \uC0AC\uC6A9\uD560 \uBA54\uBAA8\uB9AC";
            map["Smooth motion. If the area is too large for your PC, it will ask before recording."] = "\uC6C0\uC9C1\uC784\uC744 \uBD80\uB4DC\uB7FD\uAC8C \uB179\uD654\uD569\uB2C8\uB2E4. \uC774 PC\uC5D0\uC11C \uC601\uC5ED\uC774 \uB108\uBB34 \uD06C\uBA74 \uC2DC\uC791\uD558\uAE30 \uC804\uC5D0 \uC54C\uB824 \uC90D\uB2C8\uB2E4.";
            map["Half the data and workload: more headroom for large areas or modest PCs. Fast motion looks less smooth."] = "\uB370\uC774\uD130\uC640 \uBD80\uD558\uB97C \uC808\uBC18\uC73C\uB85C \uC904\uC5EC \uD070 \uC601\uC5ED\uC774\uB098 \uC800\uC0AC\uC591 PC\uC5D0 \uC801\uD569\uD569\uB2C8\uB2E4. \uBE60\uB978 \uC6C0\uC9C1\uC784\uC740 \uB35C \uBD80\uB4DC\uB7FD\uAC8C \uBCF4\uC785\uB2C8\uB2E4.";
            map["up to "] = "\uCD5C\uB300 ";
            map[" (about "] = " (\uC57D ";
            map[" s of peaks at "] = "\uCD08\uAC04 \uBE60\uB978 \uC6C0\uC9C1\uC784, ";
            map["Normal: "] = "\uBCF4\uD1B5: ";
            map[". Only uses what is needed; if full, recording stops and keeps what was recorded."] = ". \uD544\uC694\uD55C \uB9CC\uD07C\uB9CC \uC0AC\uC6A9\uD569\uB2C8\uB2E4. \uBA54\uBAA8\uB9AC\uAC00 \uAC00\uB4DD \uCC28\uBA74 \uB179\uD654\uB97C \uC911\uC9C0\uD558\uACE0 \uC9C0\uAE08\uAE4C\uC9C0\uC758 \uB0B4\uC6A9\uC744 \uC800\uC7A5\uD569\uB2C8\uB2E4.";
            map["High: "] = "\uB192\uC74C: ";
            map[". For captures that stop with heavy motion; with low free memory the PC may slow down."] = ". \uBE60\uB978 \uC6C0\uC9C1\uC784\uC5D0\uC11C \uB179\uD654\uAC00 \uBA48\uCD9C \uB54C \uC0AC\uC6A9\uD558\uC138\uC694. \uC5EC\uC720 \uBA54\uBAA8\uB9AC\uAC00 \uBD80\uC871\uD558\uBA74 PC\uAC00 \uB290\uB824\uC9C8 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
            map["Sharpness and smoothness: more bars are better. Size: file space used."] = "\uC120\uBA85\uB3C4\uC640 \uBD80\uB4DC\uB7EC\uC6C0\uC740 \uB9C9\uB300\uAC00 \uB9CE\uC744\uC218\uB85D \uC88B\uC2B5\uB2C8\uB2E4. \uD06C\uAE30\uB294 \uD30C\uC77C\uC774 \uCC28\uC9C0\uD558\uB294 \uC6A9\uB7C9\uC785\uB2C8\uB2E4.";
            map["Records what you turn on, each from the device you choose."] = "\uCF1C \uB454 \uAC01 \uC7A5\uCE58\uC5D0\uC11C \uC18C\uB9AC\uB97C \uB179\uC74C\uD569\uB2C8\uB2E4.";
            map["While recording, the bar shows each sound level and clicking the mic mutes it. Sound is synced with video and never clips even if both play at once."] = "\uB179\uD654 \uD45C\uC2DC\uC904\uC5D0\uC11C \uC18C\uB9AC \uD06C\uAE30\uB97C \uD655\uC778\uD558\uACE0 \uB9C8\uC774\uD06C\uB97C \uD074\uB9AD\uD574 \uC74C\uC18C\uAC70\uD569\uB2C8\uB2E4. \uC591\uCABD \uC18C\uB9AC\uB97C \uC601\uC0C1\uC5D0 \uB9DE\uCDB0 \uB179\uC74C\uD558\uBA70 \uB3D9\uC2DC\uC5D0 \uC7AC\uC0DD\uD574\uB3C4 \uC798\uB9AC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.";
            map["What plays on your computer: videos, calls, alerts."] = "\uB3D9\uC601\uC0C1, \uD1B5\uD654, \uC54C\uB9BC \uB4F1 \uCEF4\uD4E8\uD130\uC5D0\uC11C \uC7AC\uC0DD\uB418\uB294 \uC18C\uB9AC\uC785\uB2C8\uB2E4.";
            map["Your voice while recording, at a clear, constant volume."] = "\uB179\uD654\uD560 \uB54C \uBAA9\uC18C\uB9AC\uB97C \uB610\uB837\uD558\uACE0 \uC77C\uC815\uD55C \uC74C\uB7C9\uC73C\uB85C \uB2F4\uC2B5\uB2C8\uB2E4.";
            map["Record audio from"] = "\uB179\uC74C\uD560 \uC624\uB514\uC624 \uC7A5\uCE58";
            map["Microphone to record"] = "\uB179\uC74C\uD560 \uB9C8\uC774\uD06C";
            map["Windows default: "] = "Windows \uAE30\uBCF8\uAC12: ";
            map["No audio output available"] = "\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uC624\uB514\uC624 \uCD9C\uB825\uC774 \uC5C6\uC2B5\uB2C8\uB2E4";
            map["No microphone connected"] = "\uC5F0\uACB0\uB41C \uB9C8\uC774\uD06C\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4";
            map["Disconnected: using Windows default"] = "\uC5F0\uACB0 \uB04A\uAE40: Windows \uAE30\uBCF8\uAC12 \uC0AC\uC6A9 \uC911";
            map["Windows default"] = "Windows \uAE30\uBCF8\uAC12";
            map["Selected device"] = "\uC120\uD0DD\uD55C \uC7A5\uCE58";
            map["Camera"] = "\uCE74\uBA54\uB77C";
            map["Add your face in a bubble, like Loom."] = "Loom\uCC98\uB7FC \uC5BC\uAD74\uC744 \uC791\uC740 \uD654\uBA74\uC5D0 \uD568\uAED8 \uB2F4\uC2B5\uB2C8\uB2E4.";
            map["Appears in a corner of the recorded area. Drag it; double-click changes shape and right-click changes size."] = "\uB179\uD654 \uC601\uC5ED \uBAA8\uC11C\uB9AC\uC5D0 \uD45C\uC2DC\uD569\uB2C8\uB2E4. \uB04C\uC5B4\uC11C \uC774\uB3D9\uD558\uACE0 \uB450 \uBC88 \uD074\uB9AD\uD574 \uBAA8\uC591\uC744, \uB9C8\uC6B0\uC2A4 \uC624\uB978\uCABD \uBC84\uD2BC\uC73C\uB85C \uD06C\uAE30\uB97C \uBC14\uAFC9\uB2C8\uB2E4.";
            map["Download video engine to select camera"] = "\uCE74\uBA54\uB77C\uB97C \uC120\uD0DD\uD558\uB824\uBA74 \uB3D9\uC601\uC0C1 \uC5D4\uC9C4\uC744 \uB2E4\uC6B4\uB85C\uB4DC\uD558\uC138\uC694";
            map["Searching for cameras\u2026"] = "\uCE74\uBA54\uB77C \uAC80\uC0C9 \uC911\u2026";
            map["First one found: "] = "\uCC98\uC74C \uCC3E\uC740 \uCE74\uBA54\uB77C: ";
            map["First one found"] = "\uCC98\uC74C \uCC3E\uC740 \uCE74\uBA54\uB77C";
            map["Camera to record"] = "\uB179\uD654\uD560 \uCE74\uBA54\uB77C";
            map["Not connected now"] = "\uD604\uC7AC \uC5F0\uACB0\uB418\uC9C0 \uC54A\uC74C";
            map["No cameras found"] = "\uCE74\uBA54\uB77C\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4";
            map["Search again"] = "\uB2E4\uC2DC \uAC80\uC0C9";
            map["frames per second"] = "\uCD08\uB2F9 \uD504\uB808\uC784 \uC218";
            map["GIF frames per second"] = "GIF \uCD08\uB2F9 \uD504\uB808\uC784 \uC218";
            map["GIFs are large: 15 fps is usually the sweet spot."] = "GIF\uB294 \uD30C\uC77C\uC774 \uCEE4\uC9C0\uBBC0\uB85C \uBCF4\uD1B5 15fps\uAC00 \uC801\uB2F9\uD569\uB2C8\uB2E4.";
            map["Video engine"] = "\uB3D9\uC601\uC0C1 \uC5D4\uC9C4";
            map["Ready"] = "\uC900\uBE44\uB428";
            map["Not downloaded"] = "\uB2E4\uC6B4\uB85C\uB4DC \uC548 \uB428";
            map["FFmpeg records and encodes your videos and GIFs."] = "FFmpeg\uB85C \uB3D9\uC601\uC0C1\uACFC GIF\uB97C \uB179\uD654\uD558\uACE0 \uC778\uCF54\uB529\uD569\uB2C8\uB2E4.";
            map["Downloads automatically (~110 MB) the first time you record."] = "\uCC98\uC74C \uB179\uD654\uD560 \uB54C \uC790\uB3D9 \uB2E4\uC6B4\uB85C\uB4DC\uD569\uB2C8\uB2E4(\uC57D 110MB).";
            map["Download now"] = "\uC9C0\uAE08 \uB2E4\uC6B4\uB85C\uB4DC";
            map["Before recording"] = "\uB179\uD654 \uC804";
            map["Choosing the area shows shot options (quality, framerate, audio, camera) with the Record button, and a countdown gives you time to prepare. The countdown does not appear in the video."] = "\uC601\uC5ED\uC744 \uC120\uD0DD\uD558\uBA74 \uD654\uC9C8, \uD504\uB808\uC784\uB960, \uC624\uB514\uC624, \uCE74\uBA54\uB77C \uC124\uC815\uACFC \uB179\uD654 \uBC84\uD2BC\uC774 \uD45C\uC2DC\uB429\uB2C8\uB2E4. \uCE74\uC6B4\uD2B8\uB2E4\uC6B4 \uB3D9\uC548 \uC900\uBE44\uD560 \uC218 \uC788\uC73C\uBA70 \uC601\uC0C1\uC5D0 \uD3EC\uD568\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.";
            map["Show options before recording"] = "\uB179\uD654 \uC804 \uC635\uC158 \uD45C\uC2DC";
            map["After recording"] = "\uB179\uD654 \uD6C4";
            map["\u201CEdit\u201D on the thumbnail opens the video editor: trim start and end, change speed, size or format, add highlights and backdrops. Audio is preserved."] = "\uC378\uB124\uC77C\uC5D0\uC11C \u2018\uD3B8\uC9D1\u2019\uC744 \uB20C\uB7EC \uC601\uC0C1\uC744 \uC790\uB974\uAC70\uB098 \uC18D\uB3C4\u00B7\uD06C\uAE30\u00B7\uD615\uC2DD\uC744 \uBC14\uAFB8\uACE0 \uAC15\uC870 \uD45C\uC2DC\uC640 \uBC30\uACBD\uC744 \uCD94\uAC00\uD558\uC138\uC694. \uC624\uB514\uC624\uB294 \uC720\uC9C0\uB429\uB2C8\uB2E4.";
            map["Copy file when finished"] = "\uC644\uB8CC \uD6C4 \uD30C\uC77C \uBCF5\uC0AC";
            map["Ready to paste into chat or email right after stopping. Same setting as \u201CCopy each capture\u201D in General."] = "\uC911\uC9C0\uD558\uBA74 \uCC44\uD305\uC774\uB098 \uC774\uBA54\uC77C\uC5D0 \uBC14\uB85C \uBD99\uC5EC\uB123\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC77C\uBC18\uC758 \u2018\uBAA8\uB4E0 \uCEA1\uCC98 \uBCF5\uC0AC\u2019\uC640 \uAC19\uC740 \uC124\uC815\uC785\uB2C8\uB2E4.";
            map["Built-in player supporting all formats, audio tracks, speed, and frame-by-frame. If off, opens in the default Windows app."] = "\uB0B4\uC7A5 \uD50C\uB808\uC774\uC5B4\uC5D0\uC11C \uBAA8\uB4E0 \uC9C0\uC6D0 \uD615\uC2DD, \uC624\uB514\uC624 \uD2B8\uB799, \uC7AC\uC0DD \uC18D\uB3C4, \uD504\uB808\uC784 \uB2E8\uC704 \uC774\uB3D9\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB044\uBA74 Windows \uAE30\uBCF8 \uC571\uC73C\uB85C \uC5FD\uB2C8\uB2E4.";
            map["Open a video or Cinema master\u2026"] = "\uB3D9\uC601\uC0C1 \uB610\uB294 \uC2DC\uB124\uB9C8 \uC6D0\uBCF8 \uC5F4\uAE30\u2026";
            map["Choose \u201CPresent\u201D backdrop"] = "\uBC1C\uD45C\uC6A9 \uBC30\uACBD \uC120\uD0DD";
            map["Light and fluid, for chat and email."] = "\uAC00\uBCCD\uACE0 \uBD80\uB4DC\uB7EC\uC6CC \uCC44\uD305\uACFC \uC774\uBA54\uC77C\uC5D0 \uC801\uD569\uD569\uB2C8\uB2E4.";
            map["Sharp 60 fps, ready instantly."] = "\uC120\uBA85\uD55C 60fps \uC601\uC0C1\uC774 \uBC14\uB85C \uC900\uBE44\uB429\uB2C8\uB2E4.";
            map["Lossless 60 fps while recording."] = "\uB179\uD654 \uC911 \uBB34\uC190\uC2E4 60fps.";
            map["Lossless and verified, in MKV."] = "\uBB34\uC190\uC2E4 MKV\uB85C \uC800\uC7A5\uD558\uACE0 \uAC80\uC99D\uD569\uB2C8\uB2E4.";
            map["Sharpness"] = "\uC120\uBA85\uB3C4";
            map["Smoothness"] = "\uBD80\uB4DC\uB7EC\uC6C0";
            map["Standard: 24, 30 or 60 fps with good compression. Small files ready to share in seconds."] = "\uD45C\uC900: 24, 30, 60fps\uB85C \uD6A8\uC728\uC801\uC73C\uB85C \uC555\uCD95\uD569\uB2C8\uB2E4. \uD30C\uC77C\uC774 \uC791\uC544 \uAE08\uBC29 \uACF5\uC720\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
            map["High: 60 fps and rich detail, encoded while recording so it saves instantly. Larger files."] = "\uB192\uC74C: 60fps\uB85C \uC138\uBC00\uD558\uAC8C \uB179\uD654\uD569\uB2C8\uB2E4. \uB179\uD654\uD558\uBA70 \uC778\uCF54\uB529\uD574 \uC989\uC2DC \uC800\uC7A5\uD558\uC9C0\uB9CC \uD30C\uC77C\uC740 \uB354 \uD07D\uB2C8\uB2E4.";
            map["Maximum: 60 fps matched to your monitor rate, recorded losslessly (in areas larger than 1920 \u00D7 1200 with very high quality, but not lossless) and encoded with very high quality when finished. Takes a moment to save."] = "\uCD5C\uACE0: \uBAA8\uB2C8\uD130 \uC8FC\uC0AC\uC728\uC5D0 \uB9DE\uCDB0 60fps\uB85C \uBB34\uC190\uC2E4 \uB179\uD654\uD569\uB2C8\uB2E4. 1920 \u00D7 1200\uBCF4\uB2E4 \uD070 \uC601\uC5ED\uC5D0\uC11C\uB294 \uB9E4\uC6B0 \uB192\uC740 \uD654\uC9C8\uB85C \uB179\uD654\uD558\uBA70 \uC77C\uBD80 \uC190\uC2E4\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uC644\uB8CC \uD6C4 \uACE0\uD654\uC9C8\uB85C \uC778\uCF54\uB529\uD558\uBBC0\uB85C \uC800\uC7A5\uC5D0 \uC2DC\uAC04\uC774 \uAC78\uB9BD\uB2C8\uB2E4.";
            map["Shape"] = "\uBAA8\uC591";
            map["3 s"] = "3\uCD08";
            map["5 s"] = "5\uCD08";
            map["10 s"] = "10\uCD08";
            map["Search settings"] = "\uC124\uC815 \uAC80\uC0C9";
            map["Results"] = "\uAC80\uC0C9 \uACB0\uACFC";
            map["folder"] = "\uD3F4\uB354";
            map[" folder"] = " \uD3F4\uB354";
            map[" for an area"] = " \uC601\uC5ED \uC120\uD0DD";
            map[" to stop"] = " \uC911\uC9C0";
            map[" to record"] = " \uB179\uD654";
            map["Play with {0}"] = "{0}\uC640 \uB180\uAE30";
            map["Ask {0} something"] = "{0}\uC5D0\uAC8C \uBB3C\uC5B4\uBCF4\uAE30";
            map["Recent captures"] = "\uCD5C\uADFC \uCEA1\uCC98";
            map["View all"] = "\uC804\uCCB4 \uBCF4\uAE30";
            map["Stop recording"] = "\uB179\uD654 \uC911\uC9C0";
            map["Capture modes"] = "\uCEA1\uCC98 \uBAA8\uB4DC";
            map[", I'm"] = ", \uB0B4 \uC774\uB984\uC740";
